const router = useRouter();
const chatOpen = ref(false);
const chatStarted = ref(false);
const chatMessages = ref([{text: 'Merhaba! Size nasıl yardımcı olabilirim?', isMe: false}]);
const chatInput = ref('');
const visitorId = ref('Ziyaretci_' + Math.floor(1000 + Math.random() * 9000));
const routePath = ref(window.location.pathname);
const unreadCount = ref(0);
watch(chatOpen, (val) => { if(val) unreadCount.value = 0; });

const goToContact = () => {
   if (window.location.pathname !== '/') {
      router.push('/');
      setTimeout(() => { const el = document.getElementById('contact'); if(el) el.scrollIntoView({behavior: 'smooth'}); }, 500);
   } else {
      const el = document.getElementById('contact'); if(el) el.scrollIntoView({behavior: 'smooth'});
   }
};

let privateWs = null;

const connectChat = () => {
  const wsProtocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';

  // Sadece izole kanalına bağlanır
  privateWs = new window.WebSocket(`${wsProtocol}//${window.location.host}/api/ws/override-chat/${visitorId.value}`);

  privateWs.onopen = () => { 
      console.log('[Visitor Chat] Channel connected!');
  };

  privateWs.onmessage = (event) => {
    try {
      let data = JSON.parse(event.data);
      if (data.payload) data = typeof data.payload === 'string' ? JSON.parse(data.payload) : data.payload;

      if(data.type === 'message' && data.sender === 'admin') {
        chatMessages.value.push({ text: data.text, isMe: false });
        if (!chatOpen.value) unreadCount.value++;
        scrollToBottom();
      }
    } catch(e){}
  };

  privateWs.onclose = () => { setTimeout(connectChat, 3000); };
};

const sendChatMessage = () => {
  if(!chatInput.value || !chatInput.value.trim()) return;

  const msgText = chatInput.value.trim();
  chatMessages.value.push({ text: msgText, isMe: true });
  chatInput.value = '';
  scrollToBottom();

  if (privateWs && privateWs.readyState === 1) {
      if (!chatStarted.value) {
         // İlk mesajla beraber Admin'e bildirim gitsin
         privateWs.send(JSON.stringify({ type: 'new_chat', room: visitorId.value }));
         chatStarted.value = true;
      }
      privateWs.send(JSON.stringify({ type: 'message', room: visitorId.value, sender: 'visitor', text: msgText }));
  }
};

const scrollToBottom = () => {
  setTimeout(() => {
    const el = document.getElementById('chat-messages');
    if(el) el.scrollTop = el.scrollHeight;
  }, 50);
};

onMounted(() => {
   connectChat();
   setInterval(() => { routePath.value = window.location.pathname || ''; }, 500);
});

return { unreadCount, routePath, chatOpen, chatStarted, chatMessages, chatInput, goToContact, sendChatMessage };

