                "title": "Endüstri 4.0 ve mES: Dijital dönüşümün anahtarı",
                "slug": "endustri-4-0-ve-mes-dijital-donusumun-anahtari",
                "category": "Genel",
                "image_url": "https://override.com.tr/wp-content/uploads/2024/05/3d-rendering-industry-40-concept.jpg"
        }
   ]; // Using fallback data inside the logic instead of hardcoding all

   try {
       const res = await fetch('/api/custom/override-blogs');
       if(res.ok) { 
           const d = await res.json(); 
           let fetchedBlogs = d.data || d.records || (Array.isArray(d) ? d : []);

           // Eski logo verilerini filtrele
           fetchedBlogs = fetchedBlogs.filter(b => !b.image_url || !b.image_url.includes('logo.png'));

           if(fetchedBlogs.length > 0) {
               blogs.value = fetchedBlogs;
               loading.value = false;
               return;
           }
       }
   } catch(e) {}

   // Fallback if API fails or returns no valid blogs
   blogs.value = staticBlogs;
   loading.value = false;
});
return { blogs, loading };

const route = useRoute();
const blog = ref(null);
const loading = ref(true);
onMounted(async () => {
   const staticBlogs = [
        {
                "id": 1,
                "title": "Endüstri 4.0 ve mES: Dijital dönüşümün anahtarı",
                "slug": "endustri-4-0-ve-mes-dijital-donusumun-anahtari",
                "category": "Genel",
                "image_url": "https://override.com.tr/wp-content/uploads/2024/05/3d-rendering-industry-40-concept.jpg"
        }
   ];

   let slugStr = route?.params?.slug;
   if (!slugStr || slugStr === 'undefined') {
       const parts = window.location.pathname.split('/');
       slugStr = parts[parts.length - 1];
   }

   try {
       const res = await fetch(`/api/custom/override-blogs?slug=${slugStr}`);
       if(res.ok) { 
           const d = await res.json(); 
           if(d.data && !Array.isArray(d.data) && (!d.data.image_url || !d.data.image_url.includes('logo.png'))) {
               blog.value = d.data;
               loading.value = false;
               return;
           } else {
               const records = d.data || d.records || (Array.isArray(d) ? d : []);
               const fetched = records.find(b => b.slug === slugStr);
               if (fetched && (!fetched.image_url || !fetched.image_url.includes('logo.png'))) {
                   blog.value = fetched;
                   loading.value = false;
                   return;
               }
           }
       }
   } catch(e) {}

   blog.value = staticBlogs.find(b => b.slug === slugStr) || null;
   loading.value = false;
});
return { blog, loading };

