const blogs = ref([]);
const loading = ref(true);
const dialog = ref(false);
const valid = ref(false);
const form = ref(null);
const currentBlog = ref({ id: null, title: '', slug: '', category: '', excerpt: '', content: '', image_url: '', status: 'published' });

const headers = [
  { title: 'Görsel', key: 'image_url', sortable: false },
  { title: 'Başlık', key: 'title' },
  { title: 'Kategori', key: 'category' },
  { title: 'Durum', key: 'status' },
  { title: 'İşlemler', key: 'actions', sortable: false }
];

const fetchBlogs = async () => {
   loading.value = true;
   try {
       const res = await fetch('/api/custom/admin-blogs');
       if (res.ok) {
           const d = await res.json();
           blogs.value = d.data || [];
       }
   } catch(e) { console.error(e); }
   loading.value = false;
};

const openNewDialog = () => {
   currentBlog.value = { id: null, title: '', slug: '', category: '', excerpt: '', content: '', image_url: '', status: 'published' };
   dialog.value = true;
};

const editBlog = (item) => {
   currentBlog.value = { ...item };
   dialog.value = true;
};

const deleteBlog = async (item) => {
   if(!confirm('Bu blog yazısını silmek istediğinize emin misiniz?')) return;
   try {
       await fetch('/api/custom/admin-blogs', {
           method: 'DELETE',
           headers: { 'Content-Type': 'application/json' },
           body: JSON.stringify({ id: item.id })
       });
       fetchBlogs();
   } catch(e) { console.error(e); }
};

const saveBlog = async () => {
   try {
       const method = currentBlog.value.id ? 'PUT' : 'POST';
       await fetch('/api/custom/admin-blogs', {
           method,
           headers: { 'Content-Type': 'application/json' },
           body: JSON.stringify(currentBlog.value)
       });
       dialog.value = false;
       fetchBlogs();
   } catch(e) { console.error(e); }
};

onMounted(fetchBlogs);

return { blogs, loading, headers, dialog, valid, form, currentBlog, openNewDialog, editBlog, deleteBlog, saveBlog };

const tab = ref('chat');
const activeRooms = ref([]);
const onlineVisitors = ref([]);
const selectedRoom = ref(null);
const roomMessages = ref({});
const chatInput = ref('');
let notifyWsRef = null;

const fetchOnline = async () => {
   try {
      const res = await fetch('/api/custom/override-online-visitors');
      if (res.ok) {
         const d = await res.json();
         onlineVisitors.value = d.visitors || [];
      }
   } catch(e) {}
};

const parseData = (raw) => {
   let p = raw;
   if (p && typeof p === 'object' && p.data) p = p.data;
   if (typeof p === 'string') { try { p = JSON.parse(p); } catch(e){} }
   if (p && typeof p === 'object' && p.payload) {
       p = typeof p.payload === 'string' ? JSON.parse(p.payload) : p.payload;
   }
   return p;
};

const connectNotify = () => {
    const wsProtocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';

    // Admin sadece ve sadece güvenli admin endpointini dinler!
    notifyWsRef = new window.WebSocket(`${wsProtocol}//${window.location.host}/api/ws/override-chat-admin-notify`);

    notifyWsRef.onopen = () => {
        console.log("[ADMIN WS OPENED]");
        notifyWsRef.send(JSON.stringify({ type: 'admin_sync' }));
    };

    notifyWsRef.onmessage = (event) => {
        console.log("[ADMIN WS RECEIVED]", event.data);
        try {
            const data = parseData(event);
            if (!data) return;

            // publishWS aracılığıyla sunucudan gelen bildirimler ve mesajlar
            if (data.type === 'sync_state' && data.state) {
                const state = data.state;

                // Eğer state içinden bir oda silinmişse (kapatılmışsa), activeRooms'dan da çıkar.
                activeRooms.value = activeRooms.value.filter(r => state[r]);
                if (selectedRoom.value && !state[selectedRoom.value]) {
                    selectedRoom.value = null;
                }

                for (const room in state) {
                    if (!activeRooms.value.includes(room)) activeRooms.value.push(room);
                    roomMessages.value[room] = state[room].map(m => ({ text: m.text, isMe: m.isMe }));
                }
            }
            else if(data.type === 'new_chat' && data.room) {
               const r = data.room;
               if(!activeRooms.value.includes(r)) activeRooms.value.push(r);
            }
            else if(data.type === 'message' && data.sender === 'visitor' && data.room) {
               const r = data.room;
               if(!activeRooms.value.includes(r)) activeRooms.value.push(r);

               if(!roomMessages.value[r]) roomMessages.value[r] = [];
               roomMessages.value[r].push({ text: data.text, isMe: false });
               if(selectedRoom.value === r) scrollToBottom();
            }
        } catch(e) { console.error('WS Parse Error', e); }
    };

    notifyWsRef.onclose = () => { setTimeout(connectNotify, 3000); };
};


const contactForms = ref([]);
const headers = [
  { title: 'Tarih', key: 'created_at', width: '15%' },
  { title: 'İsim', key: 'name', width: '20%' },
  { title: 'E-Posta', key: 'email', width: '20%' },
  { title: 'Mesaj', key: 'message', width: '35%' },
  { title: 'Durum', key: 'status', width: '10%' }
];
const fetchContacts = async () => {
   try {
      const res = await fetch('/api/custom/admin-contacts');
      const data = await res.json();
      if(data.data) {
                  contactForms.value = data.data.map(item => {
            return {
               id: item.id,
               created_at: item.created_at,
               name: item.name || '',
               email: item.email || '',
               message: item.message || '',
               status: item.status || 'new'
            };
         });
      }
   } catch(e) {}
};

onMounted(() => {
  connectNotify();
  fetchContacts();
  fetchOnline();
  setInterval(fetchOnline, 5000);
});

const joinRoom = (room) => {
  if (!activeRooms.value.includes(room)) {
      activeRooms.value.push(room);
  }
  selectedRoom.value = room;
  scrollToBottom();
};

const sendReply = () => {
  if(!chatInput.value.trim() || !selectedRoom.value) return;
  const msg = chatInput.value.trim();
  const r = selectedRoom.value;

  if(!roomMessages.value[r]) roomMessages.value[r] = [];
  roomMessages.value[r].push({ text: msg, isMe: true });
  chatInput.value = '';
  scrollToBottom();

  if(notifyWsRef && notifyWsRef.readyState === 1) {
      // Cevabı kendi endpointine yollar, sunucu publishWS ile ziyaretçiye fırlatır
      notifyWsRef.send(JSON.stringify({ type: 'message', room: r, sender: 'admin', text: msg }));
  }
};

const scrollToBottom = () => {
  setTimeout(() => {
    const el = document.getElementById('admin-chat-messages');
    if(el) el.scrollTop = el.scrollHeight;
  }, 50);
};

const closeChat = () => {
  if (!selectedRoom.value) return;
  const r = selectedRoom.value;
  if(notifyWsRef && notifyWsRef.readyState === 1) {
      notifyWsRef.send(JSON.stringify({ type: 'close_chat', room: r }));
  }
  selectedRoom.value = null;
  activeRooms.value = activeRooms.value.filter(room => room !== r);
  delete roomMessages.value[r];
};

onUnmounted(() => {
  if(notifyWsRef) notifyWsRef.close();
});

return { tab, contactForms, headers, fetchContacts, 
  activeRooms, onlineVisitors, selectedRoom, roomMessages, chatInput,
  joinRoom, sendReply, closeChat
};
